  "sql": "SELECT COUNT(*) AS num_vendedores, SUM(ingresos) AS ingresos_totales FROM ( SELECT seller_id, SUM(price) AS ingresos, AVG(review_score_promedio) AS calificacion, AVG(entrega_con_retraso) AS pct_retrasos FROM vw_ingresos_por_vendedor WHERE pedidos >= 30 GROUP BY seller_id HAVING ingresos > ( SELECT PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY ingresos) FROM vw_ingresos_por_vendedor WHERE pedidos >= 30 ) AND ( calificacion < 3.5 OR pct_retrasos > 0.15 ) )"
}
